use kimo_core::color::metadata::Mastering;
fn m()->Mastering{Mastering{red:[0.68,0.32],green:[0.265,0.69],blue:[0.15,0.06],white:[0.3127,0.329],min_nits:0.005,max_nits:1000.,max_cll:1000,max_fall:400}}
#[test]fn units(){assert_eq!(m().x265().unwrap(),"hdr10=1:master-display=G(13250,34500)B(7500,3000)R(34000,16000)WP(15635,16450)L(10000000,50):max-cll=1000,400")}
#[test]fn hostile_metadata(){let mut x=m();x.max_fall=1001;assert!(x.validate().is_err());x=m();x.min_nits=f64::NAN;assert!(x.validate().is_err());x=m();x.red=[1.,1.];assert!(x.validate().is_err());x=m();x.max_nits=20000.;assert!(x.validate().is_err());x=m();x.blue=x.red;assert!(x.validate().is_err());}
#[test]fn mastering_white_triangle_and_quantization(){let mut x=m();x.white=[0.1,0.1];assert!(x.validate().is_err());x=m();x.min_nits=1.;x.max_nits=1.00000001;assert!(x.x265().is_err());x=m();std::mem::swap(&mut x.red,&mut x.blue);assert!(x.validate().is_ok());assert!(x.x265().is_ok());}
#[test]fn unrepresentable_mastering_rejected_before_mutation(){use kimo_core::commands::{Session,dispatch};use serde_json::json;let mut s=Session::new();dispatch(&mut s,"set_color_pipeline",&json!({"settings":{"enabled":true,"output_gamut":1,"output_transfer":6}})).unwrap();let mut x=m();x.min_nits=1.;x.max_nits=1.00000001;assert!(dispatch(&mut s,"set_hdr_mastering",&json!({"metadata":x})).is_err());assert!(s.project.color_pipeline.mastering.is_none());}
